CREATE TABLE IF NOT EXISTS qr_links(id SERIAL PRIMARY KEY,code VARCHAR(32) UNIQUE NOT NULL,label VARCHAR(150) NOT NULL,url TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,scans INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS qr_scans(id BIGSERIAL PRIMARY KEY,link_id INTEGER NOT NULL REFERENCES qr_links(id) ON DELETE CASCADE,scanned_at TIMESTAMPTZ NOT NULL DEFAULT now(),device VARCHAR(20) NOT NULL,os VARCHAR(20) NOT NULL,ip_hash CHAR(16) NOT NULL);CREATE INDEX IF NOT EXISTS idx_scans_link_time ON qr_scans(link_id,scanned_at);